function lookup(table, key) {
    return Object.prototype.hasOwnProperty.call(table, key) ? table[key] : "";
}

function line(value) {
    const source = value.trim();
    const exact = lookup(catalog, source) || lookup(resultMessages, source);
    if (exact) return exact;
    const prefix = source.match(/^(?:FAIL|NOTE|WARNING|Error|ValueError|RuntimeError|RuntimeFailure|LabValidationError|org\.[A-Za-z0-9_.]+):\s*(.+)$/);
    if (prefix) {
        const translated = line(prefix[1]);
        if (translated !== prefix[1] || /[\u00c0-\u1ef9]/.test(prefix[1])) return translated;
    }
    const constraint = source.match(/^(\w+) constraint failed$/);
    if (constraint) return lookup(constraints, constraint[1]) || "Cấu hình chưa đáp ứng điều kiện: " + constraint[1] + ".";
    const located = source.match(/^(.+) at (\/\S+)$/);
    if (located && lookup(resultMessages, located[1])) return lookup(resultMessages, located[1]) + " tại " + located[2] + ".";
    if (located && lookup(locations, located[1])) return lookup(locations, located[1]) + " tại " + located[2] + ".";
    const operation = source.match(/^(\w+) (requires token|requires an ordered range|step exceeds its range|requires an integer expected value) at (\/\S+)$/);
    if (operation) return operation[3] + ": " + operation[1] + " " + ({"requires token": "cần chuỗi cần thay thế.", "requires an ordered range": "cần khoảng giá trị từ nhỏ đến lớn.", "step exceeds its range": "có bước tăng vượt khoảng giá trị.", "requires an integer expected value": "cần kết quả mong đợi là số nguyên."})[operation[2]];
    const expression = source.match(/^Undefined result or goal '([^']+)' in boolean expression at (\/\S+)$/);
    if (expression) return "Kết quả hoặc mục tiêu " + expression[1] + " chưa được khai báo tại " + expression[2] + ".";
    const syntax = source.match(/^Invalid boolean expression syntax \((.+)\) at (\/\S+)$/);
    if (syntax) return "Biểu thức logic không đúng cú pháp tại " + syntax[2] + ".";
    const clone = source.match(/^Invalid IPv4 address in \+CLONE: (.+)$/);
    if (clone) return "IP của bản máy không hợp lệ: " + clone[1] + ".";
    const schema = source.match(/^Invalid Lab definition at (.+): (\w+) constraint$/);
    if (schema) return schema[1] + ": " + (lookup(constraints, schema[2]) || "Cấu hình chưa hợp lệ.");
    const subnet = source.match(/^(\d+\.\d+\.\d+\.\d+\/\d+) has host bits set$/);
    if (subnet) return "Dải mạng " + subnet[1] + " chưa đúng địa chỉ đầu mạng. Ví dụ: 10.241.10.0/24.";
    const address = source.match(/^Expected 4 octets in (.+)$/);
    if (address) return "Địa chỉ IPv4 " + address[1] + " phải gồm 4 phần, ví dụ 10.241.10.10.";
    const octet = source.match(/^(?:Octet \d+ \(> 255\) not permitted|Only decimal digits permitted|Leading zeros are not permitted|Empty octet not permitted|At most 3 characters permitted) in (.+)$/);
    if (octet) return "Địa chỉ IPv4 " + octet[1] + " không hợp lệ. Mỗi phần phải là số từ 0 đến 255, không thêm số 0 ở đầu.";
    const netmask = source.match(/^(.+) is not a valid netmask$/);
    if (netmask) return "Mặt nạ mạng " + netmask[1] + " không hợp lệ.";
    const dependency = source.match(/^(Network alias is already used|Undefined wait_for node|Node cannot wait for itself|wait_for dependency cycle): (.+)$/);
    if (dependency) return ({"Network alias is already used": "Tên thay thế đã được sử dụng: ", "Undefined wait_for node": "Máy cần chờ chưa được khai báo: ", "Node cannot wait for itself": "Máy không thể chờ chính nó: ", "wait_for dependency cycle": "Các máy đang chờ nhau theo vòng: "})[dependency[1]] + dependency[2] + ".";
    const startup = source.match(/^Node (\S+) dependency (\S+) (was not started|stopped during startup)$/);
    if (startup) return "Máy " + startup[1] + " cần máy " + startup[2] + (startup[3] === "was not started" ? " khởi động trước." : " nhưng máy đó đã dừng trong lúc khởi động.");
    const install = source.match(/^Software installation failed: (.*)$/);
    if (install) return "Cài phần mềm không thành công. Chi tiết kỹ thuật: " + install[1];
    const path = source.match(/^((?:\/|assets\/)[^\n]*?): (.+)$/);
    if (path) {
        const translated = line(path[2]);
        if (translated !== path[2]) return (path[1] === "/" ? "" : path[1] + ": ") + translated;
    }
    const kept = source.match(/^(.+); Session is kept\.$/);
    if (kept && line(kept[1]) !== kept[1]) return line(kept[1]) + " Phiên thực hành được giữ nguyên.";
    return value;
}

function text(value) {
    return String(value || "").split("\n").map(line).join("\n");
}

function issue(value) {
    return (value.path && value.path !== "/" ? value.path + ": " : "") + text(value.message);
}
